-- +goose Up

-- Theme engine v2 launch catalog: the 12 premium themes as DRAFT templates, each with its first
-- version (v1, published). Data only. The manifests are the canonical form of
-- internal/content/testdata/themes_v2/<slug>.json (what content.ValidateManifest accepts and the
-- admin API would store); a Go test runs every stored row back through the validator.
--
-- Rollout gate: status 'draft' keeps all twelve out of the host picker and the public catalog
-- (ListPublishedTemplates only returns status 'published'). Publishing a theme is an admin PATCH
-- of the template status; its v1 is already published, so that needs no further step, and setting
-- it back to 'draft' is the rollback (events pinned to the version keep rendering).
--
-- sort_order 10..120 lists these before the six original templates (1010..1060). Secondary tags
-- (kids-birthday, milestone-birthday) live in the "occasions" array, the only key the admin API
-- accepts in templates.tags; the primary occasion comes first.

INSERT INTO templates (id, slug, name, tags, status, sort_order) VALUES
