-- +goose Down

-- Dev only, same pattern as 00003 and 00004: published versions are immutable, so the trigger is
-- disabled for the delete. Fails (and the whole Down rolls back) if events pin any of these
-- versions (events -> template_versions is NO ACTION) or if a template has a later version
-- (template_versions -> templates is RESTRICT); that is intended. Repin or delete those events
-- first. Nothing is cascaded.
ALTER TABLE template_versions DISABLE TRIGGER template_versions_immutable;
DELETE FROM template_versions
WHERE version = 1
  AND template_id IN ('01926a00-0000-7000-8000-000000000007', '01926a00-0000-7000-8000-000000000008', '01926a00-0000-7000-8000-000000000009', '01926a00-0000-7000-8000-00000000000a', '01926a00-0000-7000-8000-00000000000b', '01926a00-0000-7000-8000-00000000000c', '01926a00-0000-7000-8000-00000000000d', '01926a00-0000-7000-8000-00000000000e', '01926a00-0000-7000-8000-00000000000f', '01926a00-0000-7000-8000-000000000010', '01926a00-0000-7000-8000-000000000011', '01926a00-0000-7000-8000-000000000012');
ALTER TABLE template_versions ENABLE TRIGGER template_versions_immutable;
DELETE FROM templates
WHERE id IN ('01926a00-0000-7000-8000-000000000007', '01926a00-0000-7000-8000-000000000008', '01926a00-0000-7000-8000-000000000009', '01926a00-0000-7000-8000-00000000000a', '01926a00-0000-7000-8000-00000000000b', '01926a00-0000-7000-8000-00000000000c', '01926a00-0000-7000-8000-00000000000d', '01926a00-0000-7000-8000-00000000000e', '01926a00-0000-7000-8000-00000000000f', '01926a00-0000-7000-8000-000000000010', '01926a00-0000-7000-8000-000000000011', '01926a00-0000-7000-8000-000000000012');
